$(document).ready((function(){var t=[];function n(){$("#todo-list").empty(),t.forEach((function(t,n){$("#todo-list").append('\n                    <li class="list-group-item d-flex justify-content-between align-items-center" data-index="'.concat(n,'">\n                        ').concat(t,'\n                        <div>\n                            <button class="btn btn-success btn-sm complete-task-btn">Виконано</button>\n                            <button class="btn btn-danger btn-sm delete-task-btn">Видалити</button>\n                        </div>\n                    </li>\n                '))}))}$("#add-task-btn").click((function(){var o=prompt("Введіть нове завдання:");o&&(t.push(o),n())})),$(document).on("click",".list-group-item",(function(){var n=$(this).data("index");$("#task-text").text(t[n]),$("#taskModal").modal("show")})),$(document).on("click",".complete-task-btn",(function(o){o.stopPropagation();var e=$(this).closest(".list-group-item").data("index");t[e]="✔️ ".concat(t[e]),n()})),$(document).on("click",".delete-task-btn",(function(o){o.stopPropagation();var e=$(this).closest(".list-group-item").data("index");t.splice(e,1),n()}))}));